use mip_codex::{mps,heuristic::Repair,component_objective_repair,solve::Result};
use std::time::{Instant,Duration};
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let m=mps::read(&a[1]).unwrap();let seed=vec![1.;m.variables.len()];let repair=Repair::new(&m);assert!(repair.candidate_check(&seed));let lo:Vec<_>=m.variables.iter().map(|v|v.lower).collect();let hi:Vec<_>=m.variables.iter().map(|v|v.upper).collect();let result=component_objective_repair::improve(&m,&repair,&seed,&lo,&hi,Instant::now()+Duration::from_millis(10));let(x,stats)=result.map_or((seed,None),|(x,s)|(x,Some(s)));let r=Result{status:"feasible_component_oracle".into(),objective:Some(m.objective(&x)),values:Some(m.variables.iter().zip(&x).map(|(v,&x)|(v.name.clone(),x)).collect()),component_objective_repair:stats,..Result::default()};serde_json::to_writer(std::io::stdout(),&r).unwrap();}
